CREATE TABLE application_variable_definitions (id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(36) NOT NULL,code VARCHAR(100) NOT NULL,label VARCHAR(255) NOT NULL,section_name VARCHAR(255),field_type VARCHAR(30) NOT NULL,required BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,display_order INT NOT NULL DEFAULT 0,options_json TEXT,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,CONSTRAINT fk_avd_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id),CONSTRAINT uq_avd_code UNIQUE(tenant_id,code));
CREATE TABLE application_variables (id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(36) NOT NULL,application_id VARCHAR(36) NOT NULL,definition_id VARCHAR(36) NOT NULL,code_snapshot VARCHAR(100) NOT NULL,label_snapshot VARCHAR(255) NOT NULL,section_snapshot VARCHAR(255),field_type_snapshot VARCHAR(30) NOT NULL,answer_value TEXT NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,CONSTRAINT fk_av_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id),CONSTRAINT fk_av_app FOREIGN KEY(application_id) REFERENCES loan_request_applications(id),CONSTRAINT fk_av_def FOREIGN KEY(definition_id) REFERENCES application_variable_definitions(id),CONSTRAINT uq_av_answer UNIQUE(application_id,definition_id));
CREATE INDEX idx_avd_tenant ON application_variable_definitions(tenant_id,active,display_order);
CREATE INDEX idx_av_app ON application_variables(tenant_id,application_id);
